from itertools import combinations

required_edges = [(1,2), (0,2), (1,4), (2,9), (2,7)]

# Use backtracking to find a valid 3-coloring
def find_coloring(vertex, coloring, adj):
    if vertex == 12:
        return coloring[:]

    for c in range(3):
        valid = True
        for neighbor in adj.get(vertex, []):
            if neighbor < vertex and coloring[neighbor] == c:
                valid = False
                break
        if valid:
            coloring[vertex] = c
            result = find_coloring(vertex + 1, coloring, adj)
            if result:
                return result
            coloring[vertex] = -1
    return None

# Build adjacency from required edges
adj = {}
for u, v in required_edges:
    adj.setdefault(u, []).append(v)
    adj.setdefault(v, []).append(u)

coloring = [-1] * 12
result = find_coloring(0, coloring, adj)
print("Coloring:", result)

if result:
    color_classes = {0: [], 1: [], 2: []}
    for v, c in enumerate(result):
        color_classes[c].append(v)
    print("Color classes:", color_classes)

    # Build edges - start with required
    edges = set()
    for u, v in required_edges:
        edges.add((min(u,v), max(u,v)))

    degree = [0] * 12
    for u, v in edges:
        degree[u] += 1
        degree[v] += 1

    # Add edges between different color classes to satisfy degree >= 3
    for u in range(12):
        while degree[u] < 3:
            for v in range(12):
                if u != v and result[u] != result[v]:
                    edge = (min(u,v), max(u,v))
                    if edge not in edges:
                        edges.add(edge)
                        degree[u] += 1
                        degree[v] += 1
                        if degree[u] >= 3:
                            break
            if degree[u] >= 3:
                break

    print("Degrees:", degree)
    print("All degrees >= 3:", all(d >= 3 for d in degree))
    print("Edges:", sorted(edges))

    # Verify
    for u, v in edges:
        assert result[u] != result[v]
    print("Valid!")
